import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // The constructor XBornID() is called during setUp() via new C().
        // After deployment, the sum of balances of all accounts that have non-zero balance
        // must equal the distributed amount (which is totalDistributed).
        // The bug sets owner's balance to totalSupply, making the sum > totalDistributed.
        uint256 sum = c.balanceOf(c.owner()); // ownership was emitted? No public getter. We cannot read owner directly unless it's public.
        // owner is NOT public, we cannot read it. The only public getters are balances, allowed, blacklist, name, symbol, decimals, totalSupply, totalDistributed, totalRemaining, value, distributionFinished.
        // We need to compute sum of balances. Since we cannot iterate mappings, we test a derived invariant:
        // totalSupply = totalDistributed + totalRemaining.
        // The bug does not change totalSupply or totalDistributed, so we need an invariant involving balances.
        // The only address with guaranteed balance after deployment is the deployer (this contract).
        // The deployer's address is address(this) during setUp, but XBornID() sets balances[owner] where owner = msg.sender.
        // In setUp, msg.sender is this test contract, so owner = address(this).
        // Thus we can check balances[address(this)].
        uint256 myBalance = c.balanceOf(address(this));
        // Reference: balances[address(this)] == totalDistributed
        // Bug: balances[address(this)] == totalSupply
        assertTrue(myBalance == c.totalDistributed());
    }
}

