pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address investor) public {
        // investor must not be the owner and must not be blacklisted initially
        vm.assume(investor != address(0));
        vm.assume(investor != c.owner());
        vm.assume(!c.blacklist(investor));

        // simulate owner calling XBornID
        vm.prank(c.owner());
        c.XBornID();

        // record balance before getTokens
        uint256 balanceBefore = c.balanceOf(investor);

        // non-owner investor calls getTokens with enough value
        vm.deal(investor, 100 ether);
        vm.prank(investor);
        try c.getTokens{value: 1 ether}() {
            uint256 balanceAfter = c.balanceOf(investor);
            assertTrue(balanceAfter > balanceBefore);
        } catch {
            // If it reverts, the invariant is also broken
            assertTrue(false);
        }
    }
}

