pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callerSeed, uint64 callCount) public {
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed)))));
        vm.assume(caller != address(0));
        vm.assume(callCount >= 2 && callCount <= 10);

        // Owner calls XBornID to set initial distribution
        address owner = c.owner();
        vm.prank(owner);
        c.XBornID();

        // Ensure caller is not blacklisted initially
        vm.assume(!c.blacklist(caller));

        // Record totalDistributed before any getTokens calls
        uint256 initialTotalDistributed = c.totalDistributed();

        // Advance time to allow fallback to receive if needed, but we use getTokens directly
        vm.deal(caller, 1 ether);

        uint256 prevTotalDistributed = initialTotalDistributed;
        for (uint i = 0; i < callCount; i++) {
            vm.prank(caller);
            try c.getTokens{value: 0}() {
                // getTokens might not require value; we just need it to execute
            } catch {
                // ignore reverts, we just want to observe state changes
            }
            uint256 currTotalDistributed = c.totalDistributed();
            // totalDistributed must be non-decreasing (monotonic) for any sequence of getTokens calls
            // by a non-owner, non-blacklisted caller, after initialization
            assertTrue(currTotalDistributed >= prevTotalDistributed);
            prevTotalDistributed = currTotalDistributed;
            // If caller becomes blacklisted, stop
            if (c.blacklist(caller)) break;
        }
    }
}

