pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // The constructor of C sets owner = msg.sender (this contract).
        // We call XBornID() to trigger the distribution setup.
        c.XBornID();
    }
    function testFuzz_property(address nonBlacklistedCaller) public {
        // Restrict sender to a non-zero, non-owner address that is not blacklisted.
        vm.assume(nonBlacklistedCaller != address(0));
        vm.assume(nonBlacklistedCaller != address(this));
        // The invariant: after any successful getTokens() call from a whitelisted address,
        // totalDistributed must not exceed a computed upper bound accounting for the missing
        // constructor balance. Here we check that totalDistributed is at most totalSupply
        // minus totalRemaining plus the initial owner balance (which is 0 in mutant, but
        // totalDistributed in original). Equivalently, totalDistributed + totalRemaining
        // should equal totalSupply initially, and after a distribution, totalDistributed
        // should be less than or equal to totalSupply - totalRemaining + totalDistributed_initial.
        // Since totalDistributed_initial is totalDistributed after XBornID(), we compute that.
        uint256 initialTotalDistributed = c.totalDistributed();
        uint256 initialTotalRemaining = c.totalRemaining();
        uint256 initialTotalSupply = c.totalSupply();

        // Ensure caller has enough ETH to pass the msg.value > 0 check inside getTokens (receive path requires value > 0).
        vm.deal(nonBlacklistedCaller, 1 ether);
        vm.prank(nonBlacklistedCaller);
        // getTokens() payable requires a non-zero value to be sent.
        c.getTokens{value: 1 wei}();

        // After the call, assert that totalDistributed does not exceed
        // totalSupply - totalRemaining + (initialTotalDistributed - initialOwnerBalance).
        // In the reference, the owner initially had balance == totalDistributed (so initialOwnerBalance == totalDistributed),
        // so totalDistributed <= totalSupply - totalRemaining + 0, which simplifies to totalDistributed + totalRemaining <= totalSupply.
        // In the mutant, owner balance is 0, so totalDistributed increments without the corresponding balance offset,
        // causing totalDistributed + totalRemaining > totalSupply after a distribution.
        uint256 currentTotalDistributed = c.totalDistributed();
        uint256 currentTotalRemaining = c.totalRemaining();
        uint256 currentTotalSupply = c.totalSupply();
        assertTrue(currentTotalDistributed + currentTotalRemaining <= currentTotalSupply + initialTotalDistributed - c.balanceOf(address(this)));
    }
}

