pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerTo) public {
        // Constructor already ran XBornID() in setUp, establishing state
        // We can transfer ownership and then read balances to check invariant
        vm.prank(c.owner()); // the original owner (msg.sender during setUp)
        // allow transferring ownership to a fuzzed address (could be zero or non-zero)
        c.transferOwnership(ownerTo);
        // Now the contract's totalDistributed is fixed (200M * 1e18) and totalSupply is 500M * 1e18.
        // The invariant: after only the constructor distribution, sum of all balances must equal totalDistributed.
        // Since there's no easy way to sum all balances (they are public but addresses unknown),
        // we use the invariant that the initial owner's balance must be exactly totalDistributed,
        // BUT the bug gives totalSupply to the initial owner. So we check that the balance of the initial owner
        // equals totalDistributed. Note: we know the initial owner is address(this) because setUp's msg.sender
        // is this test contract. However, to avoid hardcoding an address, we can fuzz by reading the stored owner
        // before transfer and checking that its balance equals totalDistributed.
        // Actually, we should check the original owner's balance. The original owner is stored in c.owner().
        // But we cannot read that after transferOwnership because it changes. Better: capture the original owner
        // before transfer. However, the test must have a single assertion and the fuzzer must explore.
        // We'll simply check that for the current owner (which might be the new one if transfer happened),
        // the totalDistributed invariant holds. But after transfer, the new owner has no balance.
        // A better general invariant: totalDistributed + totalRemaining == totalSupply.
        // That's always true regardless of who received tokens.
        // The bug: totalDistributed is set to 200M, totalRemaining = 300M. In buggy version, totalDistributed+totalRemaining == totalSupply still holds (both 500M).
        // However, the actual distribution of tokens breaks: balances[original owner] = totalSupply (500M), but totalDistributed == 200M.
        // The correct invariant: sum of all balances == totalDistributed (since no other distributions occur after constructor).
        // Since only the owner has a balance initially, we check balances[originalOwner] == totalDistributed.
        // To get originalOwner, we can read c.owner() before any ownership transfer. But to avoid hardcoding, we'll fuzz the address that calls the constructor? No.
        // Better: Invariant: the balance of the address stored as 'owner' at contract deployment (which is this test contract during setUp) must equal totalDistributed.
        // Since this contract is unchanged, we can just assert balances[address(this)] == totalDistributed.
        // The fuzz parameter can be something else that we vm.assume does not affect the invariant.
        vm.assume(ownerTo != address(0)); // ensure transfer is to non-zero to keep owner state valid
        // Perform ownership transfer
        vm.prank(address(this)); // we are the original owner, so prank as ourselves to call transferOwnership
        c.transferOwnership(ownerTo);
        // Now the invariant check: the original owner (address(this)) balance must equal totalDistributed because no tokens were moved yet.
        uint256 balanceOriginal = c.balanceOf(address(this));
        uint256 distributed = c.totalDistributed();
        assertTrue(balanceOriginal == distributed);
    }
}

